begin;
-- Technical inventory is proposed from the deployed catalogue. No legal
-- classification, reference, exclusion, or production approval is seeded.
create table public.dsr_all_inventory_drafts_v1(id uuid primary key default extensions.gen_random_uuid(),catalog_json jsonb not null,catalog_hash text not null check(catalog_hash~'^[a-f0-9]{64}$'),reason text not null check(length(btrim(reason))between 10 and 2000),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp());
create table public.dsr_all_inventory_source_rules_v1(draft_id uuid not null references public.dsr_all_inventory_drafts_v1(id),source_key text not null,config jsonb not null,row_version integer not null default 1,changed_by uuid not null references auth.users(id),changed_at timestamptz not null default clock_timestamp(),primary key(draft_id,source_key));
create table public.dsr_all_inventory_versions_v1(id uuid primary key default extensions.gen_random_uuid(),draft_id uuid not null unique references public.dsr_all_inventory_drafts_v1(id),version bigint generated always as identity unique,catalog_hash text not null,inventory_json jsonb not null,content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),legal_reference text not null check(length(btrim(legal_reference))between 8 and 1000),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp());
create table public.dsr_all_inventory_decisions_v1(inventory_version_id uuid primary key references public.dsr_all_inventory_versions_v1(id),content_hash text not null,decision text not null check(decision in('APPROVE','REJECT')),legal_reference text not null check(length(btrim(legal_reference))between 8 and 1000),reason text not null check(length(btrim(reason))between 10 and 2000),decided_by uuid not null references auth.users(id),decided_at timestamptz not null default clock_timestamp());
create table public.dsr_all_packages_v1(id uuid primary key default extensions.gen_random_uuid(),request_id uuid not null references public.data_subject_requests(id),scope_version_id uuid not null references public.dsr_scope_versions_v1(id),inventory_version_id uuid not null references public.dsr_all_inventory_versions_v1(id),subject_user_id uuid not null references auth.users(id),organization_id uuid not null references public.organizations(id),source_sha256 text not null check(source_sha256~'^[a-f0-9]{64}$'),snapshot_json text not null check(octet_length(snapshot_json)<=16777216),captured_at timestamptz not null,created_by uuid not null references auth.users(id),idempotency_key text not null,unique(request_id,idempotency_key));
create table public.dsr_all_exclusion_proposals_v1(id uuid primary key default extensions.gen_random_uuid(),package_id uuid not null references public.dsr_all_packages_v1(id),source_key text not null,source_hash text not null,fields text[]not null,record_hashes text[]not null,basis_code text not null check(basis_code in('THIRD_PARTY_RIGHTS','NOT_PERSONAL_DATA','LEGAL_RETENTION_RESTRICTION','LEGAL_PRIVILEGE')),legal_reference text not null check(length(btrim(legal_reference))between 8 and 1000),reason text not null check(length(btrim(reason))between 10 and 2000),content_hash text not null,proposed_by uuid not null references auth.users(id),proposed_at timestamptz not null default clock_timestamp());
create table public.dsr_all_exclusion_decisions_v1(proposal_id uuid primary key references public.dsr_all_exclusion_proposals_v1(id),content_hash text not null,decision text not null check(decision in('APPROVE','REJECT')),legal_reference text not null check(length(btrim(legal_reference))between 8 and 1000),reason text not null check(length(btrim(reason))between 10 and 2000),decided_by uuid not null references auth.users(id),decided_at timestamptz not null default clock_timestamp());
create table public.dsr_all_response_packages_v1(response_id uuid primary key references public.dsr_private_responses_v1(id),package_id uuid not null references public.dsr_all_packages_v1(id),file_manifest_hash text not null check(file_manifest_hash~'^[a-f0-9]{64}$'),disclosure_hash text not null check(disclosure_hash~'^[a-f0-9]{64}$'));
do $$declare t text;begin foreach t in array array['dsr_all_inventory_drafts_v1','dsr_all_inventory_source_rules_v1','dsr_all_inventory_versions_v1','dsr_all_inventory_decisions_v1','dsr_all_packages_v1','dsr_all_exclusion_proposals_v1','dsr_all_exclusion_decisions_v1','dsr_all_response_packages_v1']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);if t<>'dsr_all_inventory_source_rules_v1'then execute format('create trigger %I before update or delete on public.%I for each row execute function private.prevent_update_delete()',t||'_immutable',t);end if;end loop;end$$;
create function private.dsr_all_legal_staff_v1()returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select auth.uid()is not null and auth.jwt()->>'aal'='aal2'and private.has_platform_role(array['SUPER_ADMIN','COMPLIANCE_MANAGER'])$$;
revoke all on function private.dsr_all_legal_staff_v1()from public,anon,authenticated,service_role;
-- Exact business-identifier exceptions. There is no exception for Auth or
-- credential tables, and an arbitrary *_key is never assumed harmless.
create function private.dsr_all_business_identifier_v1(p_schema text,p_table text,p_column text)returns boolean language sql immutable set search_path=pg_catalog as $$select(p_schema||'.'||p_table||'.'||p_column)=any(array['public.question_bank_questions.question_key','public.question_versions.data_key','public.question_versions.template_key','public.question_rules.rule_key','public.questionnaire_sections.section_key','public.acceptance_checklists.criterion_key','public.mission_checklist_items.criterion_key','public.mission_checklist_items.deliverable_key','public.mission_checklist_items.item_key','public.mission_milestones.milestone_key','public.service_checklist_templates.criterion_key','public.service_checklist_templates.deliverable_key','public.service_checklist_templates.item_key','public.contract_items.item_key','public.deliverables.deliverable_key','public.delivery_proofs.criterion_key','public.processing_activities.activity_key','public.processing_purposes.purpose_key','public.data_categories.category_key','public.processors.provider_key','public.business_approval_policy_versions.policy_key','public.privacy_notices.notice_key','public.catalog_releases.release_key','public.quote_options.option_key','public.internal_messages.idempotency_key','public.questionnaire_session_state_events.idempotency_key','public.client_assistance_messages.idempotency_key','public.client_assistance_requests.idempotency_key','public.dsr_scope_versions_v1.idempotency_key','public.dsr_private_responses_v1.idempotency_key','public.subscription_payment_intents.idempotency_key','public.financial_journals.idempotency_key','public.credit_ledger_entries.idempotency_key','public.credit_lot_movements.idempotency_key','public.questionnaire_answers.question_key','public.questionnaire_answers.data_key','public.questionnaire_answers.option_key','public.questionnaire_answer_versions.question_key','public.questionnaire_answer_versions.data_key','public.questionnaire_answer_versions.option_key'] )$$;
revoke all on function private.dsr_all_business_identifier_v1(text,text,text)from public,anon,authenticated,service_role;
-- Auth exports have a fixed metadata allowlist. An approved inventory can
-- never override this boundary or expose provider credentials/private JSON.
create function private.dsr_all_column_exportable_v1(p_schema text,p_table text,p_column text,p_type text)returns boolean language sql immutable set search_path=pg_catalog,private as $$
 select case when private.dsr_all_business_identifier_v1(p_schema,p_table,p_column)then p_type in('text','varchar','bpchar','uuid') when p_column~*'(password|encrypted|secret|token|credential|authorization|api_?key|private_?key|hmac|access_key|ciphertext|(^|_)key($|_)|certificate_private|nonce|auth_code|code_challenge|code_verifier|signature_fingerprint)'then false
 when p_schema='auth'then case p_table when'users'then p_column=any(array['id','email','phone','created_at','updated_at','email_confirmed_at','phone_confirmed_at','last_sign_in_at','is_anonymous','banned_until'])when'sessions'then p_column=any(array['id','user_id','created_at','updated_at','not_after','aal','ip','user_agent'])when'mfa_factors'then p_column=any(array['id','user_id','friendly_name','factor_type','status','created_at','updated_at'])when'mfa_challenges'then p_column=any(array['id','factor_id','created_at','verified_at','ip_address'])when'identities'then p_column=any(array['id','user_id','provider','provider_id','created_at','updated_at','last_sign_in_at'])else false end
 when p_type in('bytea','tsvector','tsquery')or p_column in('response_json','snapshot_json','export_json','raw_body','request_body','response_body','storage_object_path','storage_path','object_path','source_storage_path','bucket_id','original_file_name','original_filename','file_name')then false
 when p_schema='private'and(p_type in('json','jsonb')or p_table~*'(credential|provider_config|hmac|oauth|secret|key_material|encryption|(^|_)keys?($|_))')then false
 when p_schema='public'and p_type in('json','jsonb')then p_table=any(array['questionnaire_answers','questionnaire_answer_versions','questionnaire_sessions','service_request_versions','client_profile_versions','user_profiles'])and p_column!~*'(proof|evidence|raw|payload|header|request_body|response_body)'
 when p_schema='storage'then p_column=any(array['id','owner','owner_id','created_at','updated_at','last_accessed_at','version','level'])
 else p_schema in('public','private')end
$$;
revoke all on function private.dsr_all_column_exportable_v1(text,text,text,text)from public,anon,authenticated,service_role;
create function private.dsr_all_column_security_secret_v1(p_schema text,p_table text,p_column text,p_type text)returns boolean language sql immutable set search_path=pg_catalog,private as $$
 select not private.dsr_all_business_identifier_v1(p_schema,p_table,p_column)and(p_column~*'(password|encrypted|secret|token|credential|authorization|api_?key|private_?key|hmac|access_key|ciphertext|(^|_)key($|_)|certificate_private|nonce|auth_code|code_challenge|code_verifier|signature_fingerprint)'or(p_schema='auth'and not private.dsr_all_column_exportable_v1(p_schema,p_table,p_column,p_type))or(p_schema='private'and p_table~*'(credential|provider_config|hmac|oauth|secret|key_material|encryption|(^|_)keys?($|_))'))
$$;
revoke all on function private.dsr_all_column_security_secret_v1(text,text,text,text)from public,anon,authenticated,service_role;
-- Only personal-container edges may propagate a subject link. Walking through
-- an organization's creator would disclose unrelated members and is forbidden.
create function private.dsr_all_fk_paths_v1(p_source oid,p_subject boolean)returns jsonb language sql stable security definer set search_path=pg_catalog,private as $$
 with recursive paths(current_id,steps,seen)as(
 select p_source,'[]'::jsonb,array[p_source]union all
 select c.confrelid,p.steps||jsonb_build_array(jsonb_build_object('source_schema',ns.nspname,'source_table',src.relname,'target_schema',nt.nspname,'target_table',dst.relname,'source_columns',(select jsonb_agg(a.attname order by u.n)from unnest(c.conkey)with ordinality u(att,n)join pg_attribute a on a.attrelid=c.conrelid and a.attnum=u.att),'target_columns',(select jsonb_agg(a.attname order by u.n)from unnest(c.confkey)with ordinality u(att,n)join pg_attribute a on a.attrelid=c.confrelid and a.attnum=u.att))),p.seen||c.confrelid
 from paths p join pg_constraint c on c.conrelid=p.current_id and c.contype='f'join pg_class src on src.oid=c.conrelid join pg_namespace ns on ns.oid=src.relnamespace join pg_class dst on dst.oid=c.confrelid join pg_namespace nt on nt.oid=dst.relnamespace
 where cardinality(p.seen)<=4 and not c.confrelid=any(p.seen)and nt.nspname in('public','auth','private','storage')and p.current_id<>case when p_subject then'auth.users'::regclass else'public.organizations'::regclass end
 and(not p_subject or c.confrelid<>'auth.users'::regclass or not exists(select 1 from pg_attribute a where a.attrelid=c.conrelid and a.attname=any(array['subject_user_id','user_id','recipient_user_id','invited_user_id','owner_user_id','support_user_id','signer_user_id','sender_user_id','actor_user_id'])and not a.attisdropped)or c.conkey@>array[(select a.attnum from pg_attribute a where a.attrelid=c.conrelid and a.attname=any(array['subject_user_id','user_id','recipient_user_id','invited_user_id','owner_user_id','support_user_id','signer_user_id','sender_user_id','actor_user_id'])and not a.attisdropped order by array_position(array['subject_user_id','user_id','recipient_user_id','invited_user_id','owner_user_id','support_user_id','signer_user_id','sender_user_id','actor_user_id'],a.attname::text)limit 1)]::smallint[])
 and(not p_subject or c.confrelid='auth.users'::regclass or(nt.nspname||'.'||dst.relname)=any(array['public.organization_memberships','public.organization_member_roles','public.questionnaire_sessions','public.internal_messages','public.client_assistance_requests','public.service_request_versions','public.user_profiles','auth.mfa_factors','auth.sessions'])))
 select coalesce(jsonb_agg(jsonb_build_object('id',private.canonical_request_hash(steps),'steps',steps)order by steps::text),'[]')from paths where current_id=case when p_subject then'auth.users'::regclass else'public.organizations'::regclass end and(p_subject or jsonb_array_length(steps)<=1 or not exists(select 1 from pg_constraint direct where direct.conrelid=p_source and direct.contype='f'and direct.confrelid='public.organizations'::regclass))
$$;
revoke all on function private.dsr_all_fk_paths_v1(oid,boolean)from public,anon,authenticated,service_role;
-- Curated financial disclosure is a first-class reviewed source, never an
-- implicit append that can bypass the approved column classifications.
create function private.dsr_all_financial_source_v1()returns jsonb language sql stable security definer set search_path=pg_catalog,private as $$
 select jsonb_build_object('key','@subject_financial_records_v1','schema','builtin','table','subject_financial_records','builtin_kind','PERSONALLY_AUTHORED_OR_SIGNED_FINANCIAL_RECORDS','columns',(select jsonb_agg(jsonb_build_object('name',f,'type','text','exportable',true,'security_secret',false,'references_user',false)order by f)from unnest(array['source','id','gateway','amount_minor','currency','billing_interval','created_at','entry_type','quantity','reference_type','reference_id','occurred_at','kind','number','issued_on','subtotal_minor','tax_minor','total_minor','original_invoice_id','invoice_id','source_hash','due_on','document_hash','contract_id','contract_version_id','signer_role','contract_hash','signed_at','amendment_id','amendment_hash','version','price_minor','content_hash','subscription_id','from_status','to_status','reason_code','model_code','meter_code','cost_minor','base_contract_version_id','amendment_number','status','price_delta_minor','deadline_delta_days','paid_on','payment_method','proof_hash','recorded_at','payment_id','allocated_minor','reconciled_at','statement_number','period_start','period_end','issued_at','mission_id','contractual_amount_minor','declared_paid_minor','confirmation_status','cash_boundary','paid_at','source_type','expires_at','revenue_value_minor','credit_lot_id','movement_type','journal_type','effective_at','supplier_invoice_id','invoice_reference','invoice_date','due_date','fiscal_status','amount_due_minor','scheduled_on','scheduled_at','scheduled_amount_minor','outbound_payment_id','event_type','provider','started_at','project_id','linked_at']::text[])f),'subject_paths',jsonb_build_array(jsonb_build_object('id',private.canonical_request_hash(to_jsonb('FINANCIAL_EXACT_VERIFIED_SUBJECT_V1'::text)),'steps','[]'::jsonb)),'organization_paths',jsonb_build_array(jsonb_build_object('id',private.canonical_request_hash(to_jsonb('FINANCIAL_EXACT_DSR_ORGANIZATION_V1'::text)),'steps','[]'::jsonb)),'hash_reference',false)
$$;
revoke all on function private.dsr_all_financial_source_v1()from public,anon,authenticated,service_role;
create function private.dsr_all_catalog_v1()returns jsonb language sql stable security definer set search_path=pg_catalog,private as $$
 with physical_sources(sources)as (select coalesce(jsonb_agg(jsonb_build_object('extractor_code_hash',private.canonical_request_hash(coalesce((select jsonb_agg(jsonb_build_object('name',p.proname,'definition',pg_get_functiondef(p.oid))order by p.proname,p.oid)from pg_proc p join pg_namespace np on np.oid=p.pronamespace where np.nspname='private'and(p.proname like'dsr_%')),'[]'::jsonb)),'key',n.nspname||'.'||c.relname,'schema',n.nspname,'table',c.relname,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',t.typname,'exportable',private.dsr_all_column_exportable_v1(n.nspname,c.relname,a.attname,t.typname),'security_secret',private.dsr_all_column_security_secret_v1(n.nspname,c.relname,a.attname,t.typname),'references_user',exists(select 1 from pg_constraint fk where fk.contype='f'and fk.conrelid=c.oid and fk.confrelid='auth.users'::regclass and a.attnum=any(fk.conkey)))order by a.attnum)from pg_attribute a join pg_type t on t.oid=a.atttypid where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'subject_paths',private.dsr_all_fk_paths_v1(c.oid,true),'organization_paths',private.dsr_all_fk_paths_v1(c.oid,false),'hash_reference',exists(select 1 from pg_attribute a where a.attrelid=c.oid and a.attname='subject_reference_hash'and not a.attisdropped))order by n.nspname,c.relname),'[]')from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private','auth','storage')and c.relkind in('r','p')and not c.relispartition)
 select physical_sources.sources||jsonb_build_array(private.dsr_all_financial_source_v1())from physical_sources
$$;
revoke all on function private.dsr_all_catalog_v1()from public,anon,authenticated,service_role;
create function private.dsr_all_path_predicate_v1(p_steps jsonb,p_alias text,p_parameter text)returns text language plpgsql immutable set search_path=pg_catalog as $$
declare step jsonb;child_alias text;joins text:='';n integer:=jsonb_array_length(p_steps);i integer;begin
 if n=0 then return format('%I.id=%s',p_alias,p_parameter);end if;
 step:=p_steps->0;child_alias:=p_alias||'_next';
 for i in 0..jsonb_array_length(step->'source_columns')-1 loop joins:=joins||case when i>0 then' and 'else''end||format('%I.%I=%I.%I',p_alias,step->'source_columns'->>i,child_alias,step->'target_columns'->>i);end loop;
 return format('exists(select 1 from %I.%I %I where %s and %s)',step->>'target_schema',step->>'target_table',child_alias,joins,private.dsr_all_path_predicate_v1(p_steps-0,child_alias,p_parameter));
end$$;
revoke all on function private.dsr_all_path_predicate_v1(jsonb,text,text)from public,anon,authenticated,service_role;
create function private.dsr_all_validate_config_v1(p_source jsonb,p_config jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog as $$
declare col jsonb;entry jsonb;k text;f text;begin
 if jsonb_typeof(p_config)is distinct from'object'or(p_config-array['mode','subject_path_id','organization_path_ids','account_global','include_null_organization','fields','excluded_fields','legal_reference','reason'])<>'{}'::jsonb or p_config->>'mode'is null or p_config->>'mode'not in('EXTRACT','EXCLUDE')or jsonb_typeof(p_config->'fields')is distinct from'array'or jsonb_typeof(p_config->'excluded_fields')is distinct from'object'or jsonb_typeof(p_config->'organization_path_ids')is distinct from'array'or jsonb_typeof(p_config->'account_global')is distinct from'boolean'or jsonb_typeof(p_config->'include_null_organization')is distinct from'boolean'or length(btrim(coalesce(p_config->>'legal_reference','')))not between 8 and 1000 or length(btrim(coalesce(p_config->>'reason','')))not between 10 and 2000 then raise exception'INVALID_DSR_SOURCE_CLASSIFICATION'using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_config->'fields')e where jsonb_typeof(e)<>'string')or(select count(*)from jsonb_array_elements(p_config->'fields'))<>(select count(distinct value)from jsonb_array_elements(p_config->'fields'))then raise exception'INVALID_DSR_SOURCE_FIELDS'using errcode='22023';end if;
 for col in select*from jsonb_array_elements(p_source->'columns')loop
  k:=col->>'name';entry:=p_config->'excluded_fields'->k;
  if(p_config->'fields')?k then
   if p_config->>'mode'='EXCLUDE'or entry is not null or not(col->>'exportable')::boolean then raise exception'DSR_NONEXPORTABLE_SOURCE_FIELD'using errcode='22023';end if;
  else
   if jsonb_typeof(entry)is distinct from'object'or(entry-array['basis_code','legal_reference','reason'])<>'{}'::jsonb or coalesce(entry->>'basis_code','')not in('SECURITY_SECRET','THIRD_PARTY_RIGHTS','NOT_PERSONAL_DATA','LEGAL_RETENTION_RESTRICTION','LEGAL_PRIVILEGE')or length(btrim(coalesce(entry->>'legal_reference','')))not between 8 and 1000 or length(btrim(coalesce(entry->>'reason','')))not between 10 and 2000 or((col->>'security_secret')::boolean and entry->>'basis_code'<>'SECURITY_SECRET')then raise exception'DSR_FIELD_EXCLUSION_REVIEW_REQUIRED'using errcode='22023';end if;
  end if;
 end loop;
 for k in select value from jsonb_array_elements_text(p_config->'fields')union select jsonb_object_keys(p_config->'excluded_fields')loop if not exists(select 1 from jsonb_array_elements(p_source->'columns')c where c->>'name'=k)then raise exception'UNKNOWN_DSR_SOURCE_FIELD'using errcode='22023';end if;end loop;
 if p_config->>'mode'='EXTRACT'then
  if(p_source->>'hash_reference')::boolean and p_config->>'subject_path_id'is distinct from'HASH_REFERENCE'then raise exception'DSR_VERIFIED_SUBJECT_LINK_REQUIRED'using errcode='22023';end if;
  if jsonb_array_length(p_config->'fields')=0 or not coalesce(p_config->>'subject_path_id'='HASH_REFERENCE'and(p_source->>'hash_reference')::boolean,false)and not exists(select 1 from jsonb_array_elements(p_source->'subject_paths')p where p->>'id'=p_config->>'subject_path_id')then raise exception'DSR_VERIFIED_SUBJECT_LINK_REQUIRED'using errcode='22023';end if;
  if(p_config->>'account_global')::boolean then if jsonb_array_length(p_source->'organization_paths')>0 or jsonb_array_length(p_config->'organization_path_ids')>0 or(p_config->>'include_null_organization')::boolean or p_config->>'subject_path_id'='HASH_REFERENCE'then raise exception'DSR_GLOBAL_ACCOUNT_SCOPE_DENIED'using errcode='22023';end if;
  else
   if jsonb_array_length(p_config->'organization_path_ids')=0 then raise exception'DSR_EXACT_ORGANIZATION_LINK_REQUIRED'using errcode='22023';end if;
   for f in select value from jsonb_array_elements_text(p_config->'organization_path_ids')loop
    if not exists(select 1 from jsonb_array_elements(p_source->'organization_paths')p where p->>'id'=f)then raise exception'UNKNOWN_DSR_ORGANIZATION_PATH'using errcode='22023';end if;
    if(p_config->>'include_null_organization')::boolean and not exists(select 1 from jsonb_array_elements(p_source->'organization_paths')p where p->>'id'=f and jsonb_array_length(p->'steps')=1 and jsonb_array_length(p#>'{steps,0,source_columns}')=1)then raise exception'DSR_GLOBAL_NULL_SCOPE_DENIED'using errcode='22023';end if;
   end loop;
  end if;
 end if;
 return p_config;
end$$;
revoke all on function private.dsr_all_validate_config_v1(jsonb,jsonb)from public,anon,authenticated,service_role;
create function public.create_dsr_all_inventory_draft_v1(p_reason text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare correlation_value uuid:=extensions.gen_random_uuid();catalog_value jsonb;h text;cached jsonb;draft uuid;result jsonb;begin
 if not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
 if length(btrim(coalesce(p_reason,'')))not between 10 and 2000 then raise exception'INVALID_DSR_INVENTORY_REASON'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('reason',btrim(p_reason)));cached:=private.begin_admin_command('privacy.all.inventory.create',p_idempotency_key,h,auth.uid());if cached is not null then return cached;end if;
 catalog_value:=private.dsr_all_catalog_v1();
 insert into public.dsr_all_inventory_drafts_v1(catalog_json,catalog_hash,reason,created_by)values(catalog_value,private.canonical_request_hash(catalog_value),btrim(p_reason),auth.uid())returning id into draft;
 result:=jsonb_build_object('outcome','DSR_ALL_INVENTORY_DRAFTED','draft_id',draft,'catalog_hash',private.canonical_request_hash(catalog_value),'source_count',jsonb_array_length(catalog_value));
 insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(auth.uid(),'USER','privacy.all.inventory.drafted','dsr_all_inventory_draft',draft::text,correlation_value,result,repeat('0',64));
 insert into public.event_outbox(aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values('dsr_all_inventory',draft::text,'DsrAllInventoryDraftedV1',correlation_value,result,'privacy-all-inventory:'||draft::text);
 perform private.finish_admin_command('privacy.all.inventory.create',p_idempotency_key,auth.uid(),result);return result;
end$$;
create function public.configure_dsr_all_inventory_source_v1(p_draft_id uuid,p_source_key text,p_expected_row_version integer,p_config jsonb,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare correlation_value uuid:=extensions.gen_random_uuid();draft public.dsr_all_inventory_drafts_v1%rowtype;rule public.dsr_all_inventory_source_rules_v1%rowtype;source jsonb;h text;cached jsonb;result jsonb;begin
 if not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
 select*into draft from public.dsr_all_inventory_drafts_v1 where id=p_draft_id for update;
 if draft.id is null or draft.created_by<>auth.uid()then raise exception'DSR_INVENTORY_DRAFT_AUTHOR_REQUIRED'using errcode='42501';end if;
 select value into source from jsonb_array_elements(draft.catalog_json)where value->>'key'=p_source_key;
 if source is null or p_expected_row_version is null or p_expected_row_version<0 then raise exception'INVALID_DSR_SOURCE_CLASSIFICATION'using errcode='22023';end if;
 perform private.dsr_all_validate_config_v1(source,p_config);
 h:=private.canonical_request_hash(jsonb_build_object('draft_id',draft.id,'source',p_source_key,'row_version',p_expected_row_version,'config',p_config));cached:=private.begin_admin_command('privacy.all.inventory.configure',p_idempotency_key,h,auth.uid());if cached is not null then return cached;end if;
 if exists(select 1 from public.dsr_all_inventory_versions_v1 where draft_id=draft.id)then raise exception'DSR_INVENTORY_ALREADY_SEALED'using errcode='55000';end if;
 select*into rule from public.dsr_all_inventory_source_rules_v1 where draft_id=draft.id and source_key=p_source_key;
 if coalesce(rule.row_version,0)is distinct from p_expected_row_version then raise exception'STALE_DSR_SOURCE_CLASSIFICATION'using errcode='40001';end if;
 insert into public.dsr_all_inventory_source_rules_v1(draft_id,source_key,config,row_version,changed_by)values(draft.id,p_source_key,p_config,1,auth.uid())on conflict(draft_id,source_key)do update set config=excluded.config,row_version=public.dsr_all_inventory_source_rules_v1.row_version+1,changed_by=excluded.changed_by,changed_at=clock_timestamp()returning*into rule;
 result:=jsonb_build_object('outcome','DSR_ALL_SOURCE_CLASSIFIED','draft_id',draft.id,'source_key',p_source_key,'row_version',rule.row_version,'config_hash',private.canonical_request_hash(p_config));
 insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(auth.uid(),'USER','privacy.all.source.classified','dsr_all_inventory_draft',draft.id::text,correlation_value,result,repeat('0',64));
 insert into public.event_outbox(aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values('dsr_all_inventory',draft.id::text,'DsrAllSourceClassifiedV1',correlation_value,result,'privacy-all-source:'||draft.id::text||':'||p_source_key||':'||rule.row_version);
 perform private.finish_admin_command('privacy.all.inventory.configure',p_idempotency_key,auth.uid(),result);return result;
end$$;
create function public.submit_dsr_all_inventory_v1(p_draft_id uuid,p_expected_catalog_hash text,p_legal_reference text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare correlation_value uuid:=extensions.gen_random_uuid();draft public.dsr_all_inventory_drafts_v1%rowtype;source jsonb;config_value jsonb;inventory jsonb:='[]';h text;cached jsonb;result jsonb;version_id uuid;begin
 if not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
 select*into draft from public.dsr_all_inventory_drafts_v1 where id=p_draft_id for update;
 if draft.id is null or draft.created_by<>auth.uid()then raise exception'DSR_INVENTORY_DRAFT_AUTHOR_REQUIRED'using errcode='42501';end if;
 if p_expected_catalog_hash is distinct from draft.catalog_hash or private.canonical_request_hash(private.dsr_all_catalog_v1())is distinct from draft.catalog_hash then raise exception'STALE_DSR_TECHNICAL_INVENTORY'using errcode='40001';end if;
 if length(btrim(coalesce(p_legal_reference,'')))not between 8 and 1000 then raise exception'DSR_LEGAL_REFERENCE_REQUIRED'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('draft_id',draft.id,'catalog_hash',p_expected_catalog_hash,'legal_reference',btrim(p_legal_reference)));cached:=private.begin_admin_command('privacy.all.inventory.submit',p_idempotency_key,h,auth.uid());if cached is not null then return cached;end if;
 for source in select value from jsonb_array_elements(draft.catalog_json)loop
  select config into config_value from public.dsr_all_inventory_source_rules_v1 where draft_id=draft.id and source_key=source->>'key';
  if config_value is null then raise exception'DSR_INVENTORY_UNCLASSIFIED_SOURCE'using errcode='55000';end if;
  perform private.dsr_all_validate_config_v1(source,config_value);inventory:=inventory||jsonb_build_array(jsonb_build_object('source',source,'config',config_value));
 end loop;
 h:=private.canonical_request_hash(jsonb_build_object('catalog_hash',draft.catalog_hash,'sources',inventory,'legal_reference',btrim(p_legal_reference)));
 insert into public.dsr_all_inventory_versions_v1(draft_id,catalog_hash,inventory_json,content_hash,legal_reference,created_by)values(draft.id,draft.catalog_hash,inventory,h,btrim(p_legal_reference),auth.uid())returning id into version_id;
 result:=jsonb_build_object('outcome','DSR_ALL_INVENTORY_SUBMITTED','inventory_version_id',version_id,'content_hash',h);
 insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(auth.uid(),'USER','privacy.all.inventory.submitted','dsr_all_inventory_version',version_id::text,correlation_value,result,repeat('0',64));
 insert into public.event_outbox(aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values('dsr_all_inventory',version_id::text,'DsrAllInventorySubmittedV1',correlation_value,result,'privacy-all-inventory-submit:'||version_id::text);
 perform private.finish_admin_command('privacy.all.inventory.submit',p_idempotency_key,auth.uid(),result);return result;
end$$;
create function public.decide_dsr_all_inventory_v1(p_inventory_version_id uuid,p_expected_content_hash text,p_approve boolean,p_review_confirmed boolean,p_legal_reference text,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare correlation_value uuid:=extensions.gen_random_uuid();v public.dsr_all_inventory_versions_v1%rowtype;result jsonb;begin
 if not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
 select*into v from public.dsr_all_inventory_versions_v1 where id=p_inventory_version_id for update;
 if v.id is null or v.created_by=auth.uid()then raise exception'DSR_INVENTORY_INDEPENDENT_REVIEW_REQUIRED'using errcode='42501';end if;
 if p_expected_content_hash is distinct from v.content_hash or private.canonical_request_hash(private.dsr_all_catalog_v1())is distinct from v.catalog_hash then raise exception'STALE_DSR_TECHNICAL_INVENTORY'using errcode='40001';end if;
 if p_approve is null or(p_approve and p_review_confirmed is distinct from true)or length(btrim(coalesce(p_legal_reference,'')))not between 8 and 1000 or length(btrim(coalesce(p_reason,'')))not between 10 and 2000 then raise exception'DSR_DOCUMENTED_LEGAL_REVIEW_REQUIRED'using errcode='22023';end if;
 insert into public.dsr_all_inventory_decisions_v1(inventory_version_id,content_hash,decision,legal_reference,reason,decided_by)values(v.id,v.content_hash,case when p_approve then'APPROVE'else'REJECT'end,btrim(p_legal_reference),btrim(p_reason),auth.uid());
 result:=jsonb_build_object('outcome','DSR_ALL_INVENTORY_REVIEWED','inventory_version_id',v.id,'content_hash',v.content_hash,'decision',case when p_approve then'APPROVE'else'REJECT'end);
 insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(auth.uid(),'USER','privacy.all.inventory.reviewed','dsr_all_inventory_version',v.id::text,correlation_value,result,repeat('0',64));
 insert into public.event_outbox(aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values('dsr_all_inventory',v.id::text,'DsrAllInventoryReviewedV1',correlation_value,result,'privacy-all-inventory-review:'||v.id::text);return result;
end$$;
create function private.dsr_all_package_context_v1(p_package_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare p public.dsr_all_packages_v1%rowtype;begin
 if not private.dsr_response_staff_v1()and auth.role()is distinct from'service_role'then raise exception'DSR_RESPONSE_STAFF_REQUIRED'using errcode='42501';end if;
 select*into p from public.dsr_all_packages_v1 where id=p_package_id;
 if p.id is null then raise exception'DSR_ALL_PACKAGE_NOT_FOUND'using errcode='22023';end if;
 return jsonb_build_object('id',p.id,'request_id',p.request_id,'scope_version_id',p.scope_version_id,'inventory_version_id',p.inventory_version_id,'subject_user_id',p.subject_user_id,'organization_id',p.organization_id,'source_sha256',p.source_sha256,'captured_at',p.captured_at,'created_by',p.created_by,'file_sources',(p.snapshot_json::jsonb)->'file_sources');
end$$;
revoke all on function private.dsr_all_package_context_v1(uuid)from public,anon,authenticated,service_role;
create function public.get_dsr_all_inventory_console_v1(p_draft_id uuid default null,p_page integer default 1,p_search text default'')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare draft public.dsr_all_inventory_drafts_v1%rowtype;drafts jsonb;versions jsonb;sources jsonb;total bigint;unclassified bigint;begin
 if not private.dsr_response_staff_v1()then raise exception'DSR_RESPONSE_STAFF_REQUIRED'using errcode='42501';end if;
 if p_page is null or p_page not between 1 and 100000 or length(coalesce(p_search,''))>200 then raise exception'INVALID_DSR_INVENTORY_PAGE'using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'created_by',created_by,'created_at',created_at,'reason',reason,'catalog_hash',catalog_hash,'source_count',jsonb_array_length(catalog_json))order by created_at desc,id),'[]')into drafts from(select*from public.dsr_all_inventory_drafts_v1 order by created_at desc,id limit 25 offset((p_page-1)*25))x;
 select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'draft_id',v.draft_id,'version',v.version::text,'content_hash',v.content_hash,'catalog_hash',v.catalog_hash,'created_by',v.created_by,'created_at',v.created_at,'legal_reference',v.legal_reference,'decision',d.decision,'decided_by',d.decided_by,'decision_reason',d.reason)order by v.version desc),'[]')into versions from(select*from public.dsr_all_inventory_versions_v1 order by version desc limit 25 offset((p_page-1)*25))v left join public.dsr_all_inventory_decisions_v1 d on d.inventory_version_id=v.id;
 if p_draft_id is not null then
  select*into draft from public.dsr_all_inventory_drafts_v1 where id=p_draft_id;
  if draft.id is null then raise exception'DSR_INVENTORY_DRAFT_NOT_FOUND'using errcode='22023';end if;
  select count(*),count(*)filter(where not exists(select 1 from public.dsr_all_inventory_source_rules_v1 r where r.draft_id=draft.id and r.source_key=e->>'key'))into total,unclassified from jsonb_array_elements(draft.catalog_json)e where p_search=''or e->>'key'ilike'%'||p_search||'%';
  select coalesce(jsonb_agg(jsonb_build_object('source',e.value,'config',r.config,'row_version',coalesce(r.row_version,0))order by e.value->>'key'),'[]')into sources from(select value from jsonb_array_elements(draft.catalog_json)where p_search=''or value->>'key'ilike'%'||p_search||'%'order by value->>'key'limit 25 offset((p_page-1)*25))e left join public.dsr_all_inventory_source_rules_v1 r on r.draft_id=draft.id and r.source_key=e.value->>'key';
 end if;
 return jsonb_build_object('can_manage',private.dsr_all_legal_staff_v1(),'actor_id',auth.uid(),'drafts',drafts,'versions',versions,'page',p_page,'lists_has_next',exists(select 1 from public.dsr_all_inventory_drafts_v1 offset(p_page*25))or exists(select 1 from public.dsr_all_inventory_versions_v1 offset(p_page*25)),'selected_draft',case when draft.id is not null then jsonb_build_object('id',draft.id,'created_by',draft.created_by,'catalog_hash',draft.catalog_hash,'catalog_current',draft.catalog_hash=private.canonical_request_hash(private.dsr_all_catalog_v1()),'sealed',exists(select 1 from public.dsr_all_inventory_versions_v1 where draft_id=draft.id),'sources',sources,'filtered_total',total,'unclassified_filtered',unclassified,'source_total',jsonb_array_length(draft.catalog_json),'has_next',total>p_page::bigint*25)end);
end$$;
revoke all on function public.create_dsr_all_inventory_draft_v1(text,text),public.configure_dsr_all_inventory_source_v1(uuid,text,integer,jsonb,text),public.submit_dsr_all_inventory_v1(uuid,text,text,text),public.decide_dsr_all_inventory_v1(uuid,text,boolean,boolean,text,text),public.get_dsr_all_inventory_console_v1(uuid,integer,text)from public,anon,authenticated,service_role;
grant execute on function public.create_dsr_all_inventory_draft_v1(text,text),public.configure_dsr_all_inventory_source_v1(uuid,text,integer,jsonb,text),public.submit_dsr_all_inventory_v1(uuid,text,text,text),public.decide_dsr_all_inventory_v1(uuid,text,boolean,boolean,text,text),public.get_dsr_all_inventory_console_v1(uuid,integer,text)to authenticated;
notify pgrst,'reload schema';
commit;
